import sys
sys.path.insert(0, '/workspace/buggy')
import io
import numpy as np
from pandas import read_csv

# Test 1: Large positive exponent (should be inf, but buggy version may return string or platform-dependent value)
try:
    df1 = read_csv(io.StringIO('data\n10E999'), float_precision='round_trip')
    val1 = df1['data'].iloc[0]
    if isinstance(val1, str):
        probe('large_exponent_10E999_is_string', 1)
    elif np.isinf(val1):
        probe('large_exponent_10E999_is_inf', float(val1))
    else:
        probe('large_exponent_10E999_value', float(val1))
except Exception as e:
    probe('large_exponent_10E999_error', 0)

# Test 2: Another large positive exponent
try:
    df2 = read_csv(io.StringIO('data\n10e99999999999'), float_precision='round_trip')
    val2 = df2['data'].iloc[0]
    if isinstance(val2, str):
        probe('large_exponent_10e99999999999_is_string', 1)
    elif np.isinf(val2):
        probe('large_exponent_10e99999999999_is_inf', float(val2))
    else:
        probe('large_exponent_10e99999999999_value', float(val2))
except Exception as e:
    probe('large_exponent_10e99999999999_error', 0)

# Test 3: Large negative exponent (should underflow to 0.0)
try:
    df3 = read_csv(io.StringIO('data\n10e-9999999999999'), float_precision='round_trip')
    val3 = df3['data'].iloc[0]
    if isinstance(val3, str):
        probe('underflow_10e-9999999999999_is_string', 1)
    else:
        probe('underflow_10e-9999999999999_value', float(val3))
except Exception as e:
    probe('underflow_10e-9999999999999_error', 0)

# Test 4: Large exponent with large mantissa
try:
    df4 = read_csv(io.StringIO('data\n50060e8007123400'), float_precision='round_trip')
    val4 = df4['data'].iloc[0]
    if isinstance(val4, str):
        probe('large_mantissa_exponent_is_string', 1)
    elif np.isinf(val4):
        probe('large_mantissa_exponent_is_inf', float(val4))
    else:
        probe('large_mantissa_exponent_value', float(val4))
except Exception as e:
    probe('large_mantissa_exponent_error', 0)

# Test 5: Invalid float token (contains 'd' in exponent, should remain string)
try:
    df5 = read_csv(io.StringIO('h1,h2,h3\ndata1,81e31d04049863b72,data3'), float_precision='round_trip')
    val5 = df5['h2'].iloc[0]
    if isinstance(val5, str) and val5 == '81e31d04049863b72':
        probe('invalid_token_kept_as_string', 1)
    elif isinstance(val5, str):
        probe('invalid_token_wrong_string', 0)
    else:
        probe('invalid_token_parsed_as_number', float(val5))
except Exception as e:
    probe('invalid_token_error', 0)

